def merge_intervals(intervals):
    if not intervals:
        return []
    sorted_ints = sorted(intervals, key=lambda x: x[0])
    merged = []
    for start, end in sorted_ints:
        if not merged or start > merged[-1][1]:
            merged.append([start, end])
        else:
            merged[-1][1] = max(merged[-1][1], end)
    return merged

import heapq

def toposort(nodes, edges):
    # Build adjacency list and indegree map
    adjacency = {node: set() for node in nodes}
    indegree = {node: 0 for node in nodes}

    for src, dst in edges:
        if src == dst:
            raise ValueError("Cycle detected: self-loop")
        if dst not in adjacency:
            raise ValueError("Edge target not in node list")
        if src not in adjacency:
            raise ValueError("Edge source not in node list")
        if dst not in adjacency[src]:
            adjacency[src].add(dst)
            indegree[dst] += 1

    # Initialize min-heap with nodes having indegree 0
    heap = [node for node in nodes if indegree[node] == 0]
    heapq.heapify(heap)

    result = []
    while heap:
        node = heapq.heappop(heap)
        result.append(node)
        for nbr in adjacency[node]:
            indegree[nbr] -= 1
            if indegree[nbr] == 0:
                heapq.heappush(heap, nbr)

    if len(result) != len(nodes):
        raise ValueError("Cycle detected")

    return result

def stable_batches(items, limit):
    if limit <= 0:
        raise ValueError("limit must be positive")
    result = []
    batch = []
    batch_weight = 0
    for name, weight in items:
        if weight <= 0 or weight > limit:
            raise ValueError("invalid weight")
        if batch_weight + weight > limit:
            if batch:
                result.append(batch)
            batch = [name]
            batch_weight = weight
        else:
            batch.append(name)
            batch_weight += weight
    if batch:
        result.append(batch)
    return result

import re

def parse_env(text: str) -> dict:
    env = {}
    key_re = re.compile(r'^[A-Za-z_][A-Za-z0-9_]*$')
    for raw_line in text.splitlines():
        line = raw_line.strip()
        if not line or line.startswith('#'):
            continue
        if '=' not in line:
            raise ValueError(f'Invalid line: {raw_line!r}')
        key, value = line.split('=', 1)
        key = key.strip()
        value = value.strip()
        if len(value) >= 2 and value[0] == value[-1] and value[0] in ("'", '"'):
            value = value[1:-1]
        if not key_re.fullmatch(key):
            raise ValueError(f'Invalid key: {key!r} in line: {raw_line!r}')
        env[key] = value
    return env

import codecs
from typing import List

def parse_sse(chunks: List[bytes]) -> List[str]:
    decoder = codecs.getincrementaldecoder("utf-8")()
    buffer = ""
    data_parts = []
    had_data = False
    result = []
    stop = False

    def dispatch_event():
        nonlocal data_parts, had_data, result, stop
        if had_data:
            event = "\n".join(data_parts)
            if event == "[DONE]":
                stop = True
                # do not add [DONE] to result
            else:
                result.append(event)
        data_parts = []
        had_data = False

    for chunk in chunks:
        if stop:
            break
        buffer += decoder.decode(chunk, final=False)
        while True:
            if stop:
                break
            if "\n" not in buffer:
                break
            line, buffer = buffer.split("\n", 1)
            if line == "":
                dispatch_event()
                if stop:
                    break
            elif line.startswith(":"):
                continue
            elif line.startswith("data:"):
                payload = line[5:]
                if payload.startswith(" "):
                    payload = payload[1:]
                data_parts.append(payload)
                had_data = True
            else:
                # ignore other fields
                continue

    if stop:
        return result

    # Flush any remaining bytes to decoder
    leftover = decoder.decode(b"", final=True)
    buffer += leftover

    # Process any complete lines after flushing
    while not stop:
        if "\n" not in buffer:
            break
        line, buffer = buffer.split("\n", 1)
        if line == "":
            dispatch_event()
            continue
        if line.startswith(":"):
            continue
        if line.startswith("data:"):
            payload = line[5:]
            if payload.startswith(" "):
                payload = payload[1:]
            data_parts.append(payload)
            had_data = True
        else:
            continue

    # At this point, any incomplete final event is discarded
    return result
